class _FakePubSub:
    def __init__(self, bus):
        self._bus = bus
        self.channels = []
    def subscribe(self, channel):
        self.channels.append(channel)
    def listen(self):
        yield {'type': 'subscribe', 'channel': 'notifications', 'data': 1}
        for ch, msg in list(self._bus):
            if ch in self.channels:
                yield {'type': 'message', 'channel': ch, 'data': msg}

class _FakePubSubRedis:
    def __init__(self):
        self.published = []
    def pubsub(self):
        return _FakePubSub(self.published)
    def publish(self, channel, data):
        self.published.append((channel, data))
        return 1

