import sqlite3

def normalize_1nf(conn: sqlite3.Connection) -> None:
    conn.execute('CREATE TABLE items_norm (id INTEGER PRIMARY KEY, title TEXT NOT NULL)')
    conn.execute(
        'CREATE TABLE item_tags ('
        'item_id INTEGER NOT NULL REFERENCES items_norm(id), '
        'tag TEXT NOT NULL, '
        'PRIMARY KEY (item_id, tag))'
    )
    rows = conn.execute('SELECT id, title, tags_csv FROM raw_items').fetchall()
    for item_id, title, tags_csv in rows:
        conn.execute('INSERT INTO items_norm (id, title) VALUES (?, ?)', (item_id, title))
        if tags_csv:
            seen = set()
            for raw_tag in tags_csv.split(','):
                tag = raw_tag.strip()
                if tag and tag not in seen:
                    seen.add(tag)
                    conn.execute(
                        'INSERT INTO item_tags (item_id, tag) VALUES (?, ?)',
                        (item_id, tag)
                    )
    conn.commit()

