import sqlite3

def create_order_with_snapshot(conn: sqlite3.Connection, order_id: int, items: list[tuple[int, int]]) -> None:
    with conn:
        conn.execute('INSERT INTO orders (id, created_at) VALUES (?, datetime("now"))', (order_id,))
        for product_id, qty in items:
            row = conn.execute('SELECT current_price FROM catalog WHERE id = ?', (product_id,)).fetchone()
            if row is None:
                raise ValueError(f'Товар {product_id} не найден в каталоге')
            conn.execute(
                'INSERT INTO order_items (order_id, product_id, qty, unit_price_snapshot) VALUES (?, ?, ?, ?)',
                (order_id, product_id, qty, row[0])
            )

def calc_order_revenue(conn: sqlite3.Connection, order_id: int) -> float:
    row = conn.execute(
        'SELECT COALESCE(SUM(qty * unit_price_snapshot), 0.0) FROM order_items WHERE order_id = ?',
        (order_id,)
    ).fetchone()
    return float(row[0])

