import sqlite3

def charge_idempotent(conn: sqlite3.Connection, idem_key: str, account_id: int, amount: float) -> dict:
    if amount <= 0:
        raise ValueError('Сумма списания должна быть положительной')
    try:
        with conn:
            conn.execute(
                'INSERT INTO idempotency_keys (idem_key, account_id, amount, status) VALUES (?, ?, ?, ?)',
                (idem_key, account_id, amount, 'applied')
            )
            cur = conn.execute(
                'UPDATE accounts SET balance = balance - ? WHERE id = ?',
                (amount, account_id)
            )
            if cur.rowcount != 1:
                raise ValueError('Счёт не найден')
            bal = conn.execute('SELECT balance FROM accounts WHERE id = ?', (account_id,)).fetchone()[0]
            return {'status': 'applied', 'balance': float(bal)}
    except sqlite3.IntegrityError as exc:
        existing = conn.execute(
            'SELECT account_id FROM idempotency_keys WHERE idem_key = ?',
            (idem_key,)
        ).fetchone()
        if existing is not None:
            bal = conn.execute('SELECT balance FROM accounts WHERE id = ?', (existing[0],)).fetchone()[0]
            return {'status': 'duplicate', 'balance': float(bal)}
        raise exc

