def reserve_stock(conn: sqlite3.Connection, sku: str, delta: int, expected_version: int) -> int:
    if delta <= 0:
        raise ValueError('Количество резерва должно быть положительным')
    with conn:
        cur = conn.execute(
            'UPDATE inventory SET qty = qty - ?, version = version + 1 '
            'WHERE sku = ? AND version = ? AND qty >= ?',
            (delta, sku, expected_version, delta)
        )
        if cur.rowcount == 1:
            return expected_version + 1
        row = conn.execute('SELECT qty, version FROM inventory WHERE sku = ?', (sku,)).fetchone()
        if row is None:
            raise KeyError(f'SKU {sku} не найден')
        if row[1] != expected_version:
            raise ConflictError(f'Версия устарела: ожидалась {expected_version}, текущая {row[1]}')
        raise ValueError(f'Недостаточно остатка: доступно {row[0]}, запрошено {delta}')

