def is_anomaly_possible(engine: str, level: str, anomaly: str) -> bool:
    if engine not in _MATRIX:
        raise ValueError(f'Неизвестный движок: {engine}')
    if level not in _MATRIX[engine]:
        raise ValueError(f'Неизвестный уровень изоляции: {level}')
    if anomaly not in _MATRIX[engine][level]:
        raise ValueError(f'Неизвестная аномалия: {anomaly}')
    return _MATRIX[engine][level][anomaly]

