def transfer_accounts(lock_mgr, tx_id: str, from_acc: int, to_acc: int, amount: float, balances: dict[int, float]) -> None:
    if from_acc == to_acc:
        return
    first, second = sorted((from_acc, to_acc))
    lock_mgr.acquire(tx_id, first)
    try:
        lock_mgr.acquire(tx_id, second)
        if balances[from_acc] < amount:
            raise ValueError('Недостаточно средств')
        balances[from_acc] -= amount
        balances[to_acc] += amount
    finally:
        lock_mgr.release_all(tx_id)

