class _FakeLockMgr:
    def __init__(self):
        self.owners = {}
        self.history = []
    def acquire(self, tx_id, res):
        self.history.append((tx_id, res))
        if res in self.owners and self.owners[res] != tx_id:
            raise DeadlockError(f'{tx_id} ждёт ресурс {res}, занятый {self.owners[res]}')
        self.owners[res] = tx_id
    def release_all(self, tx_id):
        for k in [r for r, o in self.owners.items() if o == tx_id]:
            del self.owners[k]

