def detect_deadlock_victim(wait_for: dict[str, list[str]], tx_stats: dict[str, dict]) -> str | None:
    state: dict[str, int] = {}
    path: list[str] = []

    def dfs(node: str) -> list[str] | None:
        state[node] = 1
        path.append(node)
        for nxt in wait_for.get(node, []):
            st = state.get(nxt, 0)
            if st == 1:
                idx = path.index(nxt)
                return path[idx:]
            if st == 0:
                cyc = dfs(nxt)
                if cyc is not None:
                    return cyc
        path.pop()
        state[node] = 2
        return None

    for tx in sorted(wait_for.keys()):
        if state.get(tx, 0) == 0:
            cycle = dfs(tx)
            if cycle:
                return min(
                    cycle,
                    key=lambda t: (
                        tx_stats[t]['rows_changed'],
                        tx_stats[t]['age_ms'],
                        t,
                    ),
                )
    return None

