class ReplicationRouter:
    def __init__(self, primary_lsn: int = 0, replica_lsn: int = 0, sticky_window_sec: float = 2.0):
        self.primary_lsn = primary_lsn
        self.replica_lsn = replica_lsn
        self.sticky_window_sec = sticky_window_sec
        self._last_writes: dict[str, tuple[int, float]] = {}

    def record_write(self, user_id: str, lsn: int, now: float) -> None:
        if lsn > self.primary_lsn:
            self.primary_lsn = lsn
        self._last_writes[user_id] = (lsn, now)

    def route_read(self, user_id: str, now: float) -> str:
        info = self._last_writes.get(user_id)
        if info is None:
            return 'replica'
        last_lsn, last_ts = info
        if (now - last_ts) < self.sticky_window_sec or self.replica_lsn < last_lsn:
            return 'primary'
        return 'replica'

