import heapq

def fetch_page_from_shards(shards_data: dict[str, list[dict]], offset: int, limit: int) -> list[dict]:
    if limit <= 0 or offset < 0:
        return []
    need = offset + limit
    merged = []
    for rows in shards_data.values():
        merged.extend(rows[:need])
    merged.sort(key=lambda r: (r['created_at'], r['id']), reverse=True)
    return merged[offset : offset + limit]

