import sqlite3
from dataclasses import dataclass, fields


@dataclass
class Product:
    id: int
    title: str
    category: str
    price: float
    __tablename__ = 'products'


class SelectQuery:
    def __init__(self, model_cls, where_clauses=None, params=None, order_expr=None, limit_val=None):
        self.model_cls = model_cls
        self._where = list(where_clauses or [])
        self._params = list(params or [])
        self._order = order_expr
        self._limit = limit_val

    def _clone(self, **changes):
        return SelectQuery(
            self.model_cls,
            where_clauses=changes.get('where_clauses', self._where),
            params=changes.get('params', self._params),
            order_expr=changes.get('order_expr', self._order),
            limit_val=changes.get('limit_val', self._limit),
        )

    def where(self, expr: str, *params):
        return self._clone(
            where_clauses=self._where + [expr],
            params=self._params + list(params),
        )

    def order_by(self, expr: str):
        return self._clone(order_expr=expr)

    def limit(self, n: int):
        return self._clone(limit_val=int(n))

    def compile(self) -> tuple[str, tuple]:
        cols = [f.name for f in fields(self.model_cls)]
        table = self.model_cls.__tablename__
        sql = f'SELECT {", ".join(cols)} FROM {table}'
        if self._where:
            sql += ' WHERE ' + ' AND '.join(f'({w})' for w in self._where)
        if self._order:
            sql += f' ORDER BY {self._order}'
        if self._limit is not None:
            sql += f' LIMIT {self._limit}'
        return sql, tuple(self._params)

    def scalars(self, conn: sqlite3.Connection) -> list:
        sql, params = self.compile()
        rows = conn.execute(sql, params).fetchall()
        return [self.model_cls(*row) for row in rows]


def select(model_cls) -> SelectQuery:
    return SelectQuery(model_cls)

