import sqlite3
from dataclasses import dataclass


@dataclass
class UserRecord:
    id: int
    name: str
    role: str


class IdentitySession:
    def __init__(self, conn: sqlite3.Connection):
        self.conn = conn
        self.identity_map: dict[int, UserRecord] = {}
        self._snapshots: dict[int, tuple[str, str]] = {}

    def get(self, user_id: int) -> UserRecord | None:
        if user_id in self.identity_map:
            return self.identity_map[user_id]
        row = self.conn.execute(
            'SELECT id, name, role FROM users WHERE id = ?',
            (user_id,),
        ).fetchone()
        if row is None:
            return None
        obj = UserRecord(id=row[0], name=row[1], role=row[2])
        self.identity_map[user_id] = obj
        self._snapshots[user_id] = (obj.name, obj.role)
        return obj

    def batch_upsert(self, records: list[tuple[int, str, str]]):
        if not records:
            return
        self.conn.executemany(
            'INSERT INTO users (id, name, role) VALUES (?, ?, ?) '
            'ON CONFLICT(id) DO UPDATE SET name=excluded.name, role=excluded.role',
            records,
        )
        for uid, name, role in records:
            if uid in self.identity_map:
                obj = self.identity_map[uid]
                obj.name = name
                obj.role = role

    def commit(self):
        for uid, obj in self.identity_map.items():
            snap = self._snapshots.get(uid)
            if snap != (obj.name, obj.role):
                self.conn.execute(
                    'UPDATE users SET name = ?, role = ? WHERE id = ?',
                    (obj.name, obj.role, uid),
                )
        self.conn.commit()
        for uid, obj in self.identity_map.items():
            self._snapshots[uid] = (obj.name, obj.role)

    def rollback(self):
        self.conn.rollback()
        for uid, obj in self.identity_map.items():
            if uid in self._snapshots:
                obj.name, obj.role = self._snapshots[uid]

