import sqlite3


def _split_name(full_name: str) -> tuple[str, str]:
    parts = full_name.strip().split(' ', 1)
    if len(parts) == 1:
        return parts[0], ''
    return parts[0], parts[1]


def phase_expand(conn: sqlite3.Connection):
    cols = {r[1] for r in conn.execute('PRAGMA table_info(customers)').fetchall()}
    if 'first_name' not in cols:
        conn.execute('ALTER TABLE customers ADD COLUMN first_name TEXT')
    if 'last_name' not in cols:
        conn.execute('ALTER TABLE customers ADD COLUMN last_name TEXT')
    conn.commit()


def phase_backfill(conn: sqlite3.Connection, batch_size: int = 2) -> int:
    total_updated = 0
    while True:
        rows = conn.execute(
            'SELECT id, full_name FROM customers WHERE first_name IS NULL ORDER BY id LIMIT ?',
            (batch_size,),
        ).fetchall()
        if not rows:
            break
        updates = []
        for cid, full_name in rows:
            fn, ln = _split_name(full_name)
            updates.append((fn, ln, cid))
        conn.executemany(
            'UPDATE customers SET first_name = ?, last_name = ? WHERE id = ?',
            updates,
        )
        conn.commit()
        total_updated += len(rows)
    return total_updated


def read_customer_name(conn: sqlite3.Connection, customer_id: int) -> tuple[str, str]:
    cols = {r[1] for r in conn.execute('PRAGMA table_info(customers)').fetchall()}
    if 'full_name' in cols:
        row = conn.execute(
            'SELECT full_name, first_name, last_name FROM customers WHERE id = ?',
            (customer_id,),
        ).fetchone()
        if row is None:
            raise KeyError(customer_id)
        if row[1] is not None:
            return row[1], row[2] or ''
        return _split_name(row[0])
    row = conn.execute(
        'SELECT first_name, last_name FROM customers WHERE id = ?',
        (customer_id,),
    ).fetchone()
    if row is None:
        raise KeyError(customer_id)
    return row[0], row[1]


def phase_contract(conn: sqlite3.Connection):
    conn.execute(
        'CREATE TABLE customers_new (id INTEGER PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL)'
    )
    conn.execute(
        "INSERT INTO customers_new (id, first_name, last_name) "
        "SELECT id, COALESCE(first_name, ''), COALESCE(last_name, '') FROM customers"
    )
    conn.execute('DROP TABLE customers')
    conn.execute('ALTER TABLE customers_new RENAME TO customers')
    conn.commit()

