import hashlib
import sqlite3
import time


class ChecksumMismatchError(RuntimeError):
    pass


class MigrationEngine:
    def __init__(self, conn: sqlite3.Connection):
        self.conn = conn
        self.conn.execute(
            'CREATE TABLE IF NOT EXISTS schema_migrations ('
            'version TEXT PRIMARY KEY, checksum TEXT NOT NULL, applied_at INTEGER NOT NULL)'
        )
        self.conn.commit()

    @staticmethod
    def _calc_checksum(m: dict) -> str:
        payload = (m['up'] + '\n' + m['down']).encode('utf-8')
        return hashlib.sha256(payload).hexdigest()

    def apply_pending(self, migrations: list[dict]) -> list[str]:
        applied_rows = self.conn.execute(
            'SELECT version, checksum FROM schema_migrations'
        ).fetchall()
        applied_map = {v: c for v, c in applied_rows}
        newly_applied = []
        for m in migrations:
            ver = m['version']
            csum = self._calc_checksum(m)
            if ver in applied_map:
                if applied_map[ver] != csum:
                    raise ChecksumMismatchError(f'Migration {ver} was modified after apply')
                continue
            self.conn.executescript(m['up'])
            self.conn.execute(
                'INSERT INTO schema_migrations (version, checksum, applied_at) VALUES (?, ?, ?)',
                (ver, csum, int(time.time())),
            )
            self.conn.commit()
            newly_applied.append(ver)
        return newly_applied

    def rollback_steps(self, migrations: list[dict], steps: int = 1) -> list[str]:
        if steps <= 0:
            return []
        by_ver = {m['version']: m for m in migrations}
        applied = [
            r[0]
            for r in self.conn.execute(
                'SELECT version FROM schema_migrations ORDER BY rowid DESC'
            ).fetchall()
        ]
        rolled_back = []
        for ver in applied[:steps]:
            m = by_ver[ver]
            self.conn.executescript(m['down'])
            self.conn.execute('DELETE FROM schema_migrations WHERE version = ?', (ver,))
            self.conn.commit()
            rolled_back.append(ver)
        return rolled_back

