import re


def audit_ddl(sql: str) -> list[dict]:
    findings: list[dict] = []
    statements = [s.strip() for s in sql.split(';') if s.strip()]
    for raw_stmt in statements:
        stmt = re.sub(r'\s+', ' ', raw_stmt).strip()
        upper = stmt.upper()
        if re.search(r'^CREATE\s+(?:UNIQUE\s+)?INDEX\b', upper) and 'CONCURRENTLY' not in upper:
            findings.append({
                'rule': 'INDEX_LOCK',
                'severity': 'HIGH',
                'suggestion': 'Используйте CREATE INDEX CONCURRENTLY вне транзакции.',
            })
        if re.search(r'\bADD\s+COLUMN\b', upper) and 'NOT NULL' in upper and 'DEFAULT' not in upper:
            findings.append({
                'rule': 'NOT_NULL_NO_DEFAULT',
                'severity': 'HIGH',
                'suggestion': 'Добавьте DEFAULT или создайте колонку nullable с последующим backfill.',
            })
        if re.search(r'\bALTER\s+COLUMN\b.*\bTYPE\b', upper):
            findings.append({
                'rule': 'COLUMN_TYPE_REWRITE',
                'severity': 'HIGH',
                'suggestion': 'Смена типа переписывает таблицу под блокировкой; используйте Expand-and-Contract.',
            })
        if re.search(r'\bRENAME\s+COLUMN\b', upper):
            findings.append({
                'rule': 'BREAKING_RENAME',
                'severity': 'MEDIUM',
                'suggestion': 'Переименование ломает старые инстансы; применяйте Expand-and-Contract.',
            })
        if re.search(r'\bADD\s+CONSTRAINT\b.*\bFOREIGN\s+KEY\b', upper) and 'NOT VALID' not in upper:
            findings.append({
                'rule': 'FK_FULL_SCAN',
                'severity': 'MEDIUM',
                'suggestion': 'Создавайте внешний ключ с NOT VALID, а затем выполняйте VALIDATE CONSTRAINT.',
            })
    return findings

