safe_sql = '''
CREATE INDEX CONCURRENTLY idx_orders_user ON orders(user_id);
ALTER TABLE orders ADD COLUMN note TEXT;
ALTER TABLE orders ADD CONSTRAINT fk_user FOREIGN KEY (user_id) REFERENCES users(id) NOT VALID;
'''
assert audit_ddl(safe_sql) == [], f'Безопасный DDL не должен давать предупреждений: {audit_ddl(safe_sql)}'

bad_sql = '''
CREATE INDEX idx_bad ON orders(status);
alter table orders add column
    code varchar(10) not null;
ALTER TABLE orders ALTER COLUMN amount TYPE BIGINT;
ALTER TABLE orders RENAME COLUMN old_col TO new_col;
ALTER TABLE orders ADD CONSTRAINT fk_u FOREIGN KEY (user_id) REFERENCES users(id);
'''
res = audit_ddl(bad_sql)
rules = [r['rule'] for r in res]
assert rules == ['INDEX_LOCK', 'NOT_NULL_NO_DEFAULT', 'COLUMN_TYPE_REWRITE', 'BREAKING_RENAME', 'FK_FULL_SCAN'], f'Неверный набор правил: {rules}'
assert res[0]['severity'] == 'HIGH' and 'CONCURRENTLY' in res[0]['suggestion']
assert res[1]['severity'] == 'HIGH' and 'DEFAULT' in res[1]['suggestion']
assert res[3]['severity'] == 'MEDIUM' and 'Expand-and-Contract' in res[3]['suggestion']
assert res[4]['severity'] == 'MEDIUM' and 'NOT VALID' in res[4]['suggestion']

