def run_alembic_cycle(conn: sqlite3.Connection, revisions: list, target: str) -> str | None:
    conn.execute('CREATE TABLE IF NOT EXISTS alembic_version (version_num TEXT NOT NULL)')
    row = conn.execute('SELECT version_num FROM alembic_version').fetchone()
    current = row[0] if row else None

    order = []
    parent = None
    by_parent = {r.down_revision: r for r in revisions}
    while parent in by_parent:
        nxt = by_parent[parent]
        order.append(nxt)
        parent = nxt.revision

    by_rev = {r.revision: r for r in order}
    if target == 'head':
        start_idx = order.index(by_rev[current]) + 1 if current else 0
        for rev in order[start_idx:]:
            rev.upgrade(conn)
            current = rev.revision
    elif target == 'base':
        start_idx = order.index(by_rev[current]) if current else -1
        for i in range(start_idx, -1, -1):
            order[i].downgrade(conn)
            current = order[i].down_revision
    else:
