def _parents_of(down_rev) -> list[str]:
    if down_rev is None:
        return []
    if isinstance(down_rev, tuple):
        return list(down_rev)
    return [down_rev]


def find_heads(revisions: dict) -> list[str]:
    referenced = set()
    for down in revisions.values():
        referenced.update(_parents_of(down))
    return sorted(r for r in revisions if r not in referenced)


def _ancestors(revisions: dict, start: str) -> dict[str, int]:
    dist = {}
    queue = [(start, 0)]
    while queue:
        node, d = queue.pop(0)
        if node in dist:
            continue
        dist[node] = d
        for p in _parents_of(revisions.get(node)):
            queue.append((p, d + 1))
    return dist


def find_merge_base(revisions: dict, head_a: str, head_b: str):
    anc_a = _ancestors(revisions, head_a)
    anc_b = _ancestors(revisions, head_b)
    common = set(anc_a) & set(anc_b)
    if not common:
        return None
    return min(common, key=lambda n: anc_a[n] + anc_b[n])


def create_merge_revision(revisions: dict, new_rev_id: str) -> tuple[dict, list[str]]:
    heads = find_heads(revisions)
    if len(heads) < 2:
        raise ValueError('Need at least 2 heads to merge')
    updated = dict(revisions)
    updated[new_rev_id] = tuple(heads)

    children: dict[str, list[str]] = {r: [] for r in updated}
    indeg: dict[str, int] = {}
    for rev, down in updated.items():
        ps = _parents_of(down)
        indeg[rev] = len(ps)
        for p in ps:
            children[p].append(rev)
    ready = sorted(r for r, d in indeg.items() if d == 0)
    plan = []
    while ready:
        cur = ready.pop(0)
        plan.append(cur)
        for ch in sorted(children[cur]):
            indeg[ch] -= 1
            if indeg[ch] == 0:
                ready.append(ch)
                ready.sort()
    return updated, plan

