def analyze_autogenerate_diff(model_schema: dict, db_schema: dict) -> list[dict]:
    warnings: list[dict] = []
    for table, m_tbl in sorted(model_schema.items()):
        d_tbl = db_schema.get(table)
        if not d_tbl:
            continue
        m_cols = m_tbl.get('columns', {})
        d_cols = d_tbl.get('columns', {})
        added = {k: v for k, v in m_cols.items() if k not in d_cols}
        removed = {k: v for k, v in d_cols.items() if k not in m_cols}

        renamed_new = set()
        for r_name, r_meta in sorted(removed.items()):
            for a_name, a_meta in sorted(added.items()):
                if a_name not in renamed_new and a_meta.get('type') == r_meta.get('type'):
                    warnings.append({
                        'kind': 'POSSIBLE_RENAME',
                        'table': table,
                        'detail': f'{r_name} -> {a_name} ({r_meta.get("type")})',
                    })
                    renamed_new.add(a_name)
                    break

        for a_name, a_meta in sorted(added.items()):
            if a_name in renamed_new:
                continue
            if a_meta.get('nullable') is False and a_meta.get('server_default') is None:
                warnings.append({
                    'kind': 'MISSING_SERVER_DEFAULT',
                    'table': table,
                    'detail': a_name,
                })

        m_idx = m_tbl.get('indexes', {})
        d_idx = d_tbl.get('indexes', {})
        for idx_name, m_imeta in sorted(m_idx.items()):
            if idx_name in d_idx and m_imeta.get('where') != d_idx[idx_name].get('where'):
                warnings.append({
                    'kind': 'PARTIAL_INDEX_IGNORED',
                    'table': table,
                    'detail': idx_name,
                })

        m_enums = m_tbl.get('enums', {})
        d_enums = d_tbl.get('enums', {})
        for e_name, m_vals in sorted(m_enums.items()):
            if e_name in d_enums and list(m_vals) != list(d_enums[e_name]):
                warnings.append({
                    'kind': 'ENUM_CHANGED',
                    'table': table,
                    'detail': e_name,
                })
    return warnings

