def jsonb_contains(doc, sub) -> bool:
    if isinstance(sub, dict):
        if not isinstance(doc, dict):
            return False
        for k, v in sub.items():
            if k not in doc or not jsonb_contains(doc[k], v):
                return False
        return True
    if isinstance(sub, list):
        if not isinstance(doc, list):
            return False
        return all(any(jsonb_contains(d_item, s_item) for d_item in doc) for s_item in sub)
