class ClusterSimulator:
    def __init__(self, mode: str, nodes: int = 3):
        if mode not in ('CP', 'AP'):
            raise ValueError('mode must be CP or AP')
        self.mode = mode
        self.nodes = nodes
        self._data = [{} for _ in range(nodes)]
        self._segments: list[set[int]] | None = None
        self._dirty_during_partition: list[set[str]] = [set() for _ in range(nodes)]

    def _segment_of(self, node_id: int) -> set[int]:
        if self._segments is None:
            return set(range(self.nodes))
        for seg in self._segments:
            if node_id in seg:
                return seg
        raise ValueError(f'Node {node_id} not in any segment')

    def partition(self, group_a: list[int], group_b: list[int]):
        self._segments = [set(group_a), set(group_b)]
        self._dirty_during_partition = [set() for _ in range(self.nodes)]

    def write(self, node_id: int, key: str, value) -> dict:
        seg = self._segment_of(node_id)
        if self._segments is not None and self.mode == 'CP':
            if len(seg) <= self.nodes / 2:
                return {'ok': False, 'error': 'QUORUM_UNAVAILABLE'}
        cur_ver = max((self._data[n].get(key, (None, 0))[1] for n in seg), default=0)
        new_ver = cur_ver + 1
        for n in seg:
            self._data[n][key] = (value, new_ver)
            if self._segments is not None:
                self._dirty_during_partition[n].add(key)
        return {'ok': True, 'version': new_ver}

    def heal(self) -> list[str]:
        if self._segments is None:
            return []
        seg_a, seg_b = self._segments
        keys_a = set().union(*(self._dirty_during_partition[n] for n in seg_a))
        keys_b = set().union(*(self._dirty_during_partition[n] for n in seg_b))
        conflicts = sorted(keys_a & keys_b)
        all_keys = set().union(*(d.keys() for d in self._data))
        for k in all_keys:
            best = max((d[k] for d in self._data if k in d), key=lambda x: x[1])
            for d in self._data:
                d[k] = best
        self._segments = None
        self._dirty_during_partition = [set() for _ in range(self.nodes)]
        return conflicts

