    if isinstance(obj, list):
        res = []
        for item in obj:
            res.extend(_extract_values(item, parts))
        return res
    if isinstance(obj, dict) and head in obj:
        return _extract_values(obj[head], tail)
    return [_MISSING]


def _match_op(val, cond) -> bool:
    if isinstance(cond, dict) and any(k.startswith('$') for k in cond):
        for op, target in cond.items():
            if op == '$exists':
                exists = val is not _MISSING
                if exists != bool(target):
                    return False
                continue
            if val is _MISSING:
                return False
            if op == '$eq' and val != target:
                return False
            elif op == '$ne' and val == target:
                return False
            elif op == '$gt' and not (val > target):
                return False
            elif op == '$gte' and not (val >= target):
                return False
            elif op == '$lt' and not (val < target):
                return False
            elif op == '$lte' and not (val <= target):
                return False
            elif op == '$in':
                if isinstance(val, list):
                    if not any(x in target for x in val):
                        return False
                elif val not in target:
                    return False
        return True
    if val is _MISSING:
        return False
    if isinstance(val, list):
        return cond in val or val == cond
    return val == cond


def _match_doc(doc: dict, query: dict) -> bool:
