def _get_path(doc: dict, expr: str):
    path = expr[1:] if expr.startswith('$') else expr
    cur = doc
    for part in path.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur[part]
        else:
            return None
    return cur


def _match_simple(doc: dict, conds: dict) -> bool:
    for field, target in conds.items():
        val = _get_path(doc, field)
        if isinstance(target, dict):
            for op, rhs in target.items():
                if val is None:
                    return False
                if op == '$eq' and val != rhs:
                    return False
                elif op == '$gt' and not (val > rhs):
                    return False
                elif op == '$gte' and not (val >= rhs):
                    return False
                elif op == '$lt' and not (val < rhs):
                    return False
                elif op == '$lte' and not (val <= rhs):
                    return False
                elif op == '$in' and val not in rhs:
                    return False
        elif val != target:
            return False
    return True


def run_pipeline(docs: list[dict], stages: list[dict]) -> list[dict]:
    stream = [dict(d) for d in docs]
    for stage in stages:
        if '$match' in stage:
            cond = stage['$match']
            stream = [d for d in stream if _match_simple(d, cond)]
        elif '$unwind' in stage:
            field = stage['$unwind'].lstrip('$')
            new_stream = []
            for d in stream:
                arr = d.get(field)
                if isinstance(arr, list):
                    for item in arr:
                        copy_d = dict(d)
                        copy_d[field] = item
                        new_stream.append(copy_d)
            stream = new_stream
        elif '$group' in stage:
            spec = stage['$group']
            id_expr = spec['_id']
            groups: dict = {}
            for d in stream:
                gkey = _get_path(d, id_expr) if isinstance(id_expr, str) and id_expr.startswith('$') else id_expr
                groups.setdefault(gkey, []).append(d)
            out = []
            for gkey, items in groups.items():
                row = {'_id': gkey}
                for out_field, acc in spec.items():
                    if out_field == '_id':
                        continue
                    if '$sum' in acc:
                        arg = acc['$sum']
                        if isinstance(arg, (int, float)):
                            row[out_field] = sum(arg for _ in items)
                        else:
                            row[out_field] = sum((_get_path(it, arg) or 0) for it in items)
                    elif '$avg' in acc:
                        vals = [_get_path(it, acc['$avg']) for it in items if _get_path(it, acc['$avg']) is not None]
                        row[out_field] = sum(vals) / len(vals) if vals else 0.0
                    elif '$push' in acc:
                        row[out_field] = [_get_path(it, acc['$push']) for it in items]
                out.append(row)
            stream = out
        elif '$sort' in stage:
            for field, direction in reversed(list(stage['$sort'].items())):
                stream.sort(key=lambda d: d.get(field), reverse=(direction == -1))
        elif '$limit' in stage:
            stream = stream[:int(stage['$limit'])]
        elif '$project' in stage:
            proj = stage['$project']
            include_keys = [k for k, v in proj.items() if v == 1]
            exclude_keys = {k for k, v in proj.items() if v == 0}
            new_stream = []
            for d in stream:
                if include_keys:
                    nd = {k: d[k] for k in include_keys if k in d}
                    if '_id' in d and proj.get('_id', 1) != 0 and '_id' not in nd:
                        nd['_id'] = d['_id']
                else:
                    nd = {k: v for k, v in d.items() if k not in exclude_keys}
                new_stream.append(nd)
            stream = new_stream
    return stream

