class DeviceTelemetryStore:
    def __init__(self, bucket_size: int = 3):
        self.bucket_size = bucket_size
        self.buckets: list[dict] = []

    def record_event(self, device_id: str, ts: int, value: float):
        target = None
        for b in reversed(self.buckets):
            if b['device_id'] == device_id and b['count'] < self.bucket_size:
                target = b
                break
        if target is None:
            target = {
                'device_id': device_id,
                'count': 0,
                'min_ts': ts,
                'max_ts': ts,
                'events': [],
            }
            self.buckets.append(target)
        target['events'].append({'ts': ts, 'value': value})
        target['count'] += 1
        if ts < target['min_ts']:
            target['min_ts'] = ts
        if ts > target['max_ts']:
            target['max_ts'] = ts

    def query_events(self, device_id: str, start_ts: int, end_ts: int) -> list[dict]:
        res = []
        for b in self.buckets:
            if b['device_id'] != device_id:
                continue
            if b['max_ts'] < start_ts or b['min_ts'] > end_ts:
                continue
            for ev in b['events']:
                if start_ts <= ev['ts'] <= end_ts:
                    res.append(ev)
        res.sort(key=lambda e: e['ts'])
        return res

