    result = list(stages)
    changed = True
    while changed:
        changed = False
        for i in range(1, len(result)):
            cur = result[i]
            prev = result[i - 1]
            if '$match' not in cur:
                continue
            match_keys = set(cur['$match'].keys())
            if '$unwind' in prev:
                unwound = prev['$unwind'].lstrip('$')
                if any(k == unwound or k.startswith(unwound + '.') for k in match_keys):
                    continue
                result[i - 1], result[i] = cur, prev
                changed = True
            elif '$sort' in prev:
                result[i - 1], result[i] = cur, prev
                changed = True
            elif '$group' in prev:
                group_out = set(prev['$group'].keys())
                if match_keys & group_out:
                    continue
                result[i - 1], result[i] = cur, prev
                changed = True
    return result


def validate_esr_index(
    index_fields: list[str],
    equality_fields: set[str],
    sort_fields: list[str],
    range_fields: set[str],
) -> tuple[bool, str]:
    phase = 0
    seen_sort = []
    for f in index_fields:
        if f in equality_fields:
            if phase > 0:
                return False, f'Equality field {f} must come before Sort/Range'
        elif f in sort_fields:
            if phase > 1:
                return False, f'Sort field {f} must come before Range'
            phase = 1
            seen_sort.append(f)
        elif f in range_fields:
            phase = 2
        else:
            return False, f'Unused field {f} in index'
    if seen_sort != list(sort_fields):
        return False, 'Sort fields order or completeness mismatch'
    if not equality_fields.issubset(index_fields):
        return False, 'Missing equality fields in index'
    if not range_fields.issubset(index_fields):
        return False, 'Missing range fields in index'
    return True, 'OK'

