import math
import time


class MiniRedisTTL:
    def __init__(self, clock=None):
        self.clock = clock or time.monotonic
        self._store: dict[str, tuple] = {}

    def _purge_if_expired(self, key: str) -> bool:
        item = self._store.get(key)
        if item is None:
            return True
        _, exp = item
        if exp is not None and self.clock() >= exp:
            del self._store[key]
            return True
        return False

    def set(self, key: str, value, ex: float | None = None, keepttl: bool = False):
        now = self.clock()
        if ex is not None:
            exp = now + ex
        elif keepttl:
            self._purge_if_expired(key)
            exp = self._store[key][1] if key in self._store else None
        else:
            exp = None
        self._store[key] = (value, exp)

    def get(self, key: str):
        if self._purge_if_expired(key):
            return None
        return self._store[key][0]

    def ttl(self, key: str) -> int:
        if self._purge_if_expired(key):
            return -2
        exp = self._store[key][1]
        if exp is None:
            return -1
        return max(0, int(math.ceil(exp - self.clock())))

    def persist(self, key: str) -> bool:
        if self._purge_if_expired(key):
            return False
        val, exp = self._store[key]
        if exp is None:
            return False
        self._store[key] = (val, None)
        return True

    def active_expire_cycle(self, sample_keys: list[str] | None = None) -> int:
        targets = list(sample_keys) if sample_keys is not None else list(self._store.keys())
        removed = 0
        for k in targets:
            if k in self._store and self._purge_if_expired(k):
                removed += 1
        return removed

