_VALID_POLICIES = {'noeviction', 'allkeys-lru', 'volatile-lru', 'allkeys-lfu', 'volatile-ttl'}


class EvictingCache:
    def __init__(self, capacity: int, policy: str = 'allkeys-lru'):
        if policy not in _VALID_POLICIES:
            raise ValueError(f'Unknown policy: {policy}')
        self.capacity = capacity
        self.policy = policy
        self._tick = 0
        self._data: dict[str, dict] = {}

    def _next_tick(self) -> int:
        self._tick += 1
        return self._tick

    def _evict_one(self):
        if self.policy == 'noeviction':
            raise OutOfMemoryError('OOM command not allowed when used memory > maxmemory')
        if self.policy.startswith('volatile-'):
            candidates = [(k, m) for k, m in self._data.items() if m['ttl'] is not None]
            if not candidates:
                raise OutOfMemoryError('No volatile keys to evict')
        else:
            candidates = list(self._data.items())

        if self.policy in ('allkeys-lru', 'volatile-lru'):
            victim = min(candidates, key=lambda item: item[1]['last_access'])[0]
        elif self.policy == 'allkeys-lfu':
            victim = min(candidates, key=lambda item: (item[1]['freq'], item[1]['last_access']))[0]
        elif self.policy == 'volatile-ttl':
            victim = min(candidates, key=lambda item: (item[1]['ttl'], item[1]['last_access']))[0]
        del self._data[victim]

    def set(self, key: str, value, ttl: int | None = None):
        t = self._next_tick()
        if key in self._data:
            self._data[key]['value'] = value
            self._data[key]['ttl'] = ttl
            self._data[key]['last_access'] = t
            self._data[key]['freq'] += 1
            return
        if len(self._data) >= self.capacity:
            self._evict_one()
        self._data[key] = {'value': value, 'ttl': ttl, 'last_access': t, 'freq': 1}

    def get(self, key: str):
        if key not in self._data:
            return None
        self._data[key]['last_access'] = self._next_tick()
        self._data[key]['freq'] += 1
        return self._data[key]['value']

    def keys(self) -> 'set[str]':
        return set(self._data.keys())

