class LeaderboardZSet:
    def __init__(self):
        self._scores: dict[str, float] = {}

    def _ordered(self) -> list[tuple[str, float]]:
        return sorted(self._scores.items(), key=lambda kv: (-kv[1], kv[0]))

    def zadd(self, member: str, score: float):
        self._scores[member] = float(score)

    def zincrby(self, member: str, delta: float) -> float:
        new_score = self._scores.get(member, 0.0) + float(delta)
        self._scores[member] = new_score
        return new_score

    def zrevrange(self, start: int, stop: int, withscores: bool = False) -> list:
        items = self._ordered()
        n = len(items)
        if start < 0:
            start = max(0, n + start)
        if stop < 0:
            stop = n + stop
        if start >= n or stop < start:
            return []
        sliced = items[start:stop + 1]
        return sliced if withscores else [m for m, _ in sliced]

    def zrevrank(self, member: str) -> int | None:
        if member not in self._scores:
            return None
        for idx, (m, _) in enumerate(self._ordered()):
            if m == member:
                return idx
        return None

