class SlidingWindowLimiter:
    def __init__(self, limit: int, window_sec: float):
        self.limit = limit
        self.window_sec = float(window_sec)
        self._logs: dict[str, list[float]] = {}

    def allow(self, client_id: str, now: float) -> tuple[bool, float]:
        cutoff = now - self.window_sec
        log = [ts for ts in self._logs.get(client_id, []) if ts > cutoff]
        if len(log) < self.limit:
            log.append(now)
            self._logs[client_id] = log
            return True, 0.0
        self._logs[client_id] = log
        oldest = log[0]
        retry_after = max(0.0, oldest + self.window_sec - now)
        return False, retry_after

