import fnmatch


class RedisKeyspace:
    def __init__(self, keys: list[str]):
        self._keys = list(keys)

    def keys(self, pattern: str) -> list[str]:
        raise RuntimeError('BLOCKING KEYS * IS FORBIDDEN IN PRODUCTION!')

    def scan(self, cursor: int = 0, match: str | None = None, count: int = 10) -> tuple[int, list[str]]:
        if count <= 0:
            raise ValueError('count must be > 0')
        n = len(self._keys)
        if cursor >= n or n == 0:
            return 0, []
        end = min(n, cursor + count)
        chunk = self._keys[cursor:end]
        if match is not None:
            chunk = [k for k in chunk if fnmatch.fnmatchcase(k, match)]
        next_cursor = 0 if end >= n else end
        return next_cursor, chunk


def scan_all(redis_sim: RedisKeyspace, match: str, count: int = 10) -> list[str]:
    cursor = 0
    collected: list[str] = []
    while True:
        cursor, batch = redis_sim.scan(cursor=cursor, match=match, count=count)
        collected.extend(batch)
        if cursor == 0:
            break
    return collected

