class MiniRedisTxn:
    def __init__(self):
        self._data: dict[str, object] = {}
        self._versions: dict[str, int] = {}
        self._watched: dict[str, int] = {}
        self._in_multi = False
        self._queue: list[tuple] = []

    def _apply_set(self, key: str, val):
        self._data[key] = val
        self._versions[key] = self._versions.get(key, 0) + 1
        return 'OK'

    def _apply_incr(self, key: str, delta: int = 1):
        new_val = int(self._data.get(key, 0)) + delta
        self._data[key] = new_val
        self._versions[key] = self._versions.get(key, 0) + 1
        return new_val

    def get(self, key: str):
        return self._data.get(key)

    def set(self, key: str, val):
        if self._in_multi:
            self._queue.append(('set', key, val))
            return 'QUEUED'
        return self._apply_set(key, val)

    def incr(self, key: str, delta: int = 1):
        if self._in_multi:
            self._queue.append(('incr', key, delta))
            return 'QUEUED'
        return self._apply_incr(key, delta)

    def watch(self, key: str):
        self._watched[key] = self._versions.get(key, 0)

    def multi(self):
        self._in_multi = True
        self._queue.clear()

    def exec(self) -> list | None:
        dirty = any(self._versions.get(k, 0) != v for k, v in self._watched.items())
        queued = list(self._queue)
        self._in_multi = False
        self._queue.clear()
        self._watched.clear()
        if dirty:
            return None
        results = []
        for cmd in queued:
            if cmd[0] == 'set':
                results.append(self._apply_set(cmd[1], cmd[2]))
            elif cmd[0] == 'incr':
                results.append(self._apply_incr(cmd[1], cmd[2]))
        return results

    def discard(self):
        self._in_multi = False
        self._queue.clear()
        self._watched.clear()

