import functools
import json

_MISS = object()


def cached(store: dict, namespace: str, version: str = 'v1'):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            payload = json.dumps({'args': args, 'kwargs': kwargs}, sort_keys=True)
            key = f'{namespace}:{version}:{func.__name__}:{payload}'
            raw = store.get(key, _MISS)
            if raw is not _MISS:
                return json.loads(raw)
            result = func(*args, **kwargs)
            store[key] = json.dumps(result)
            return result
        return wrapper
    return decorator

