        self.db = db
        self.cache: dict[str, tuple] = {}
        self.db_calls = 0
        self.negative_ttl = negative_ttl
        self.bloom = SimpleBloomFilter(size=256)
        for pid in valid_ids:
            self.bloom.add(str(pid))

    def get_product(self, product_id: int, now: float = 0.0) -> dict | None:
        if not self.bloom.might_contain(str(product_id)):
            return None
        key = f'product:{product_id}'
        if key in self.cache:
            val, exp = self.cache[key]
            if exp is None or now < exp:
                return None if val == self._NULL_SENTINEL else val
        self.db_calls += 1
        prod = self.db.get(product_id)
        if prod is not None:
            self.cache[key] = (prod, None)
        else:
            self.cache[key] = (self._NULL_SENTINEL, now + self.negative_ttl)
        return prod

