class SingleflightCache:
    def __init__(self, db_loader):
        self.db_loader = db_loader
        self.cache: dict[str, object] = {}
        self._locks: set[str] = set()
        self.db_calls = 0

    def acquire_or_wait(self, key: str) -> tuple[str, object]:
        if key in self.cache:
            return 'HIT', self.cache[key]
        if key in self._locks:
            return 'WAIT', None
        self._locks.add(key)
        try:
            if key in self.cache:
                return 'HIT', self.cache[key]
            self.db_calls += 1
            val = self.db_loader(key)
            self.cache[key] = val
            return 'LEADER', val
        finally:
            self._locks.discard(key)

    def fetch_concurrent(self, key: str, n_requests: int) -> list:
        if n_requests <= 0:
            return []
        results = []
        if key not in self.cache and key not in self._locks:
            self._locks.add(key)
            waiters = 0
            for i in range(n_requests):
                if i == 0:
                    continue
                status, _ = self.acquire_or_wait(key)
                if status == 'WAIT':
                    waiters += 1
            try:
                if key not in self.cache:
                    self.db_calls += 1
                    val = self.db_loader(key)
                    self.cache[key] = val
                results.append(self.cache[key])
            finally:
                self._locks.discard(key)
            for _ in range(waiters):
                _, val = self.acquire_or_wait(key)
                results.append(val)
            return results

        for _ in range(n_requests):
            _, val = self.acquire_or_wait(key)
            results.append(val)
        return results

