class WriteBehindStore:
    def __init__(self, cache: dict, db_writer):
        self.cache = cache
        self.db_writer = db_writer
        self._dirty: list[str] = []
        self._dirty_set: set[str] = set()

    def write(self, key: str, value):
        self.cache[key] = value
        if key not in self._dirty_set:
            self._dirty_set.add(key)
            self._dirty.append(key)

    def pending_count(self) -> int:
        return len(self._dirty)

    def flush(self, batch_size: int | None = None) -> int:
        if not self._dirty:
            return 0
        limit = len(self._dirty) if batch_size is None else min(batch_size, len(self._dirty))
        batch_keys = self._dirty[:limit]
        payload = [(k, self.cache[k]) for k in batch_keys]
        self.db_writer(payload)
        self._dirty = self._dirty[limit:]
        for k in batch_keys:
            self._dirty_set.discard(k)
        return len(batch_keys)

