        new_ver = self.get_tag_version(tag) + 1
        self._tag_versions[tag] = new_ver
        return new_ver

    def set(self, key: str, value, tags: list[str] | None = None):
        tag_snap = {t: self.get_tag_version(t) for t in (tags or [])}
        self._entries[key] = (value, tag_snap)

    def get(self, key: str):
        entry = self._entries.get(key)
        if entry is None:
            return None
        val, tag_snap = entry
        for tag, ver in tag_snap.items():
            if self.get_tag_version(tag) != ver:
                return None
        return val

