def canonical_cache_key(path: str, query_params: dict[str, str], allowed_params: set[str]) -> str:
    norm_path = path.strip().lower()
    if len(norm_path) > 1:
        norm_path = norm_path.rstrip('/')
    filtered = [
        (k, str(query_params[k]))
        for k in sorted(query_params.keys())
        if k in allowed_params
    ]
    if not filtered:
        return f'page:{norm_path}'
    qstr = '&'.join(f'{k}={v}' for k, v in filtered)
    return f'page:{norm_path}?{qstr}'

